package run.ikaros.planning; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentPlanningImportantDateService implements PlanningImportantDateService {private final PlanningImportantDateRepository dates;public PersistentPlanningImportantDateService(PlanningImportantDateRepository d){dates=d;}public Mono<PlanningImportantDateView> create(UUID owner,CreatePlanningImportantDateRequest r){Instant n=Instant.now();return dates.save(new PlanningImportantDateEntity(null,owner,r.title().trim(),r.description(),r.occursAt(),r.timeZone()==null?"UTC":r.timeZone(),r.kind(),PlanningImportantDateStatus.ACTIVE,n,n,null)).map(this::view);}public Flux<PlanningImportantDateView> list(UUID owner){return dates.findAllByOwnerIdOrderByOccursAtAsc(owner).map(this::view);}public Mono<PlanningImportantDateView> update(UUID owner,UUID id,UpdatePlanningImportantDateRequest r){return owned(owner,id).flatMap(old->{if(old.status()==PlanningImportantDateStatus.ARCHIVED)return Mono.error(new ConflictException("已归档日期不能修改"));if((old.version()==null?0:old.version())!=r.expectedVersion())return Mono.error(new ConflictException("Important Date 版本冲突"));return dates.save(new PlanningImportantDateEntity(old.id(),old.ownerId(),r.title().trim(),r.description(),r.occursAt(),r.timeZone()==null?old.timeZone():r.timeZone(),r.kind(),old.status(),old.createdAt(),Instant.now(),old.version()));}).map(this::view);}public Mono<PlanningImportantDateView> archive(UUID owner,UUID id){return owned(owner,id).flatMap(old->dates.save(new PlanningImportantDateEntity(old.id(),old.ownerId(),old.title(),old.description(),old.occursAt(),old.timeZone(),old.kind(),PlanningImportantDateStatus.ARCHIVED,old.createdAt(),Instant.now(),old.version()))).map(this::view);}private Mono<PlanningImportantDateEntity> owned(UUID owner,UUID id){return dates.findById(id).filter(x->x.ownerId().equals(owner)).switchIfEmpty(Mono.error(new NotFoundException("Important Date 不存在")));}private PlanningImportantDateView view(PlanningImportantDateEntity x){return new PlanningImportantDateView(x.id(),x.ownerId(),x.title(),x.description(),x.occursAt(),x.timeZone(),x.kind(),x.status(),x.createdAt(),x.updatedAt(),x.version()==null?0:x.version());}}
